//! Corpus manifests: a feature's case rows and expected results.
//!
//! A feature commits either its whole manifest (`harness/features/<id>/corpus.json`)
//! or only its pins (`pins.json`: each case id with the work the reference folds),
//! or takes another feature's cases and pins (`cases_from`), in which case the
//! rows are generated by the candidate's input generator ([`crate::generators`]) and the manifest is read at
//! that same `corpus.json` path.
//! Either way its identity is the SHA-256 of its bytes: a generated manifest's are
//! its canonical JSON, exactly what the generator writes, so the identity is
//! deterministic.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use crate::json::{self, Value};
use crate::sha256;

/// The manifest at `path` and the SHA-256 of its bytes.
pub fn read(root: &Path, path: &Path) -> Result<(Value, String), String> {
    if path.exists() {
        let bytes = fs::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
        let text = std::str::from_utf8(&bytes).map_err(|e| format!("{}: {e}", path.display()))?;
        let value = json::parse(text).map_err(|e| format!("{}: {e}", path.display()))?;
        return Ok((value, sha256::hex(&bytes)));
    }
    let value =
        generated(root, path).ok_or_else(|| format!("{}: no such manifest", path.display()))??;
    Ok((value.clone(), sha256::hex(canonical(&value).as_bytes())))
}

/// Check the declared membership and pin coverage before a required report.
pub fn validate_required(contract: &Value, manifest: &Value) -> Result<(), String> {
    let cases = manifest
        .get("cases")
        .and_then(Value::as_array)
        .filter(|cases| !cases.is_empty())
        .ok_or("required manifest has no cases")?;
    let mut ids = BTreeSet::new();
    let mut profiles = BTreeSet::new();
    let work_fields = contract
        .get("worker_operation")
        .and_then(Value::as_str)
        .map(|_| super::comparison::work_fields(contract))
        .transpose()?;
    let per_target = crate::generators::pinned_per_target(contract);
    let targets = contract
        .get("required_targets")
        .and_then(Value::as_array)
        .unwrap_or_default();
    if work_fields.is_some() && per_target && targets.is_empty() {
        return Err("per-target pins need required targets".into());
    }
    for case in cases {
        let id = case
            .get("id")
            .and_then(Value::as_str)
            .filter(|id| !id.is_empty())
            .ok_or("required manifest has a case without an ID")?;
        if !ids.insert(id) {
            return Err(format!("duplicate case ID {id}"));
        }
        if let Some(profile) = case.get("profile").and_then(Value::as_str) {
            profiles.insert(profile.to_owned());
        }
        let Some(fields) = &work_fields else {
            continue;
        };
        let expected = case.get("expected");
        let pins = case.get(crate::generators::EXPECTED_BY_TARGET);
        if per_target {
            if expected.is_some() {
                return Err(format!("{id}: expected must use per-target folds"));
            }
            let unpinned = crate::generators::unpinned(contract, id);
            for target in targets {
                let target = target.as_str().ok_or("invalid required target")?;
                if let Some(pin) = pins.and_then(|pins| pins.get(target)) {
                    super::comparison::work_summary(pin, fields)
                        .map_err(|error| format!("{id}: expected fold for {target}: {error}"))?;
                } else if !unpinned
                    .iter()
                    .any(|&(name, reason)| name == target && !reason.is_empty())
                {
                    return Err(format!("{id}: missing expected fold for {target}"));
                }
            }
        } else {
            if pins.is_some() {
                return Err(format!("{id}: per-target folds require pinned_per_target"));
            }
            let expected = expected.ok_or_else(|| format!("{id}: missing expected fold"))?;
            super::comparison::work_summary(expected, fields)
                .map_err(|error| format!("{id}: expected fold: {error}"))?;
        }
    }
    let missing = super::acceptance::missing_profiles(contract, &profiles);
    if !missing.is_empty() {
        return Err(format!("missing required profiles: {}", missing.join(", ")));
    }
    Ok(())
}

/// The bytes a manifest or pin file is committed or written as.
pub fn canonical(value: &Value) -> String {
    json::to_python(value, Some(2)) + "\n"
}

/// The files a manifest is made from: itself, or the pins it takes and what the
/// rows are generated from.
pub fn sources(root: &Path, path: &Path) -> Vec<PathBuf> {
    if path.exists() {
        return vec![path.to_path_buf()];
    }
    let id = path
        .parent()
        .and_then(Path::file_name)
        .and_then(|n| n.to_str())
        .unwrap_or_default();
    let contract = crate::checks::read_json(&path.with_file_name("contract.json")).ok();
    match contract.as_ref().and_then(crate::generators::for_contract) {
        Some(generator) => generator
            .inputs(root, id)
            .iter()
            .map(|f| root.join(f))
            .collect(),
        None => vec![path.with_file_name("pins.json")],
    }
}

/// The generated manifest for a `corpus.json` path beside a generated feature's
/// contract.
pub(crate) fn generated(root: &Path, path: &Path) -> Option<Result<Value, String>> {
    if path.file_name().is_none_or(|n| n != "corpus.json")
        || !path.with_file_name("contract.json").is_file()
    {
        return None;
    }
    let id = path.parent().and_then(Path::file_name)?.to_str()?;
    let document = match crate::checks::read_json(&path.with_file_name("contract.json")) {
        Ok(document) => document,
        Err(error) => return Some(Err(error)),
    };
    let generator = crate::generators::for_contract(&document)?;
    Some(generator.manifest(root, id))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn required_manifest_rejects_missing_profiles_and_pins() {
        let contract =
            json::parse(r#"{"worker_operation":"test-","required_profiles":["first","second"]}"#)
                .unwrap();
        let without_profile =
            json::parse(r#"{"cases":[{"id":"one","profile":"first","expected":{"packets":1,"bytes":1,"digest":1}}]}"#).unwrap();
        assert_eq!(
            validate_required(&contract, &without_profile).unwrap_err(),
            "missing required profiles: second"
        );
        let without_pin = json::parse(
            r#"{"cases":[{"id":"one","profile":"first","expected":{"packets":1,"bytes":1,"digest":1}},
                          {"id":"two","profile":"second"}]}"#,
        )
        .unwrap();
        assert_eq!(
            validate_required(&contract, &without_pin).unwrap_err(),
            "two: missing expected fold"
        );
    }

    #[test]
    fn required_manifest_accepts_declared_target_exceptions() {
        let manifest = json::parse(
            r#"{"cases":[{"id":"one","profile":"sample","expected_by_target":{"first":{"packets":1,"bytes":1,"digest":1}}}]}"#,
        )
        .unwrap();
        let contract = |exceptions: &str| {
            json::parse(&format!(
                r#"{{"worker_operation":"test-","required_profiles":["sample"],
                    "pinned_per_target":true,"required_targets":["first","second"],
                    "unpinned_targets":{exceptions}}}"#,
            ))
            .unwrap()
        };
        assert_eq!(
            validate_required(&contract("[]"), &manifest).unwrap_err(),
            "one: missing expected fold for second"
        );
        let allowed =
            contract(r#"[{"id":"one","targets":["second"],"reason":"Host-dependent fold"}]"#);
        validate_required(&allowed, &manifest).unwrap();
        let malformed = json::parse(
            r#"{"cases":[{"id":"one","profile":"sample","expected_by_target":{"first":{}}}]}"#,
        )
        .unwrap();
        assert!(
            validate_required(&allowed, &malformed)
                .unwrap_err()
                .contains("expected fold for first")
        );
        let shadowed = json::parse(
            r#"{"cases":[{"id":"one","profile":"sample","expected":{"packets":1,"bytes":1,"digest":1},
                "expected_by_target":{"first":{"packets":1,"bytes":1,"digest":1}}}]}"#,
        )
        .unwrap();
        assert_eq!(
            validate_required(&allowed, &shadowed).unwrap_err(),
            "one: expected must use per-target folds"
        );
    }

    #[test]
    fn required_repository_manifests_cover_every_declared_profile() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        for contract in super::super::features::required(root).unwrap() {
            let (manifest, _) = read(root, &contract.manifest()).unwrap();
            if let Err(error) = validate_required(&contract.document, &manifest) {
                panic!("{}: {error}", contract.id);
            }
        }
    }
}
